template:
@php
    // The switch says where the place is; a block saved before it had a value reads the contacts, as new ones do.
    $mode = in_array($source, ['coordinates', 'embed'], true) ? $source : 'settings';
    // What the component would refuse is not handed to it: a number off the earth is no number,
    // a code that is not Google's map is no map — the field refuses it, a page written before must not break.
    $lat = is_numeric($latitude) && abs((float) $latitude) <= 90 ? (float) $latitude : null;
    $lng = is_numeric($longitude) && abs((float) $longitude) <= 180 ? (float) $longitude : null;
    $frame = $mode === 'embed' && is_string($embed ?? null) ? \WebxUi\Widgets\Map\GoogleMapsEmbed::address($embed) : null;
    $scale = is_numeric($zoom) ? max(1, min(19, (int) round((float) $zoom))) : 15;
    $heights = ['small' => '16em', 'medium' => '24em', 'large' => '32em'];
    $tall = $heights[$height] ?? '24em';
    $narrow = $heights[$height_narrow ?? ''] ?? null;
    $place = $address ? wx_text($address)->plain() : null;
    $name = ($title ?? null) ? wx_text($title)->plain() : null;
    $open = is_string($link ?? null) && preg_match('~^https?://~i', trim($link)) === 1 ? trim($link) : null;
    $contacts = $mode === 'settings' ? \WebxUi\Widgets\Contacts\ContactsSource::get()?->primaryAddress() : null;
    // On: this block does not wait for consent, whatever the site says; off — and a block saved
    // before the switch — the site decides, which by default is to wait.
    $free = in_array($at_once ?? null, [true, 1, '1'], true) ? false : null;
    $shown = match ($mode) {
        'settings' => $contacts !== null,
        'embed' => $frame !== null,
        default => $lat !== null && $lng !== null,
    };
@endphp
@if ($shown)
<section @class(['b-map', 'site-bleed' => ($width ?? null) === 'bleed']) data-wx-block="map">
    @if ($heading)
        <h2 class="b-map__heading">{{ $heading }}</h2>
    @endif
    @if ($mode === 'embed')
        <x-webx-map :embed="$frame" :height="$tall" :height-narrow="$narrow" :address="$place" :title="$name" :consent="$free" :link="$open" />
    @elseif ($mode === 'settings')
        <x-webx-map from="settings" :zoom="$scale" :height="$tall" :height-narrow="$narrow" :title="$name" :consent="$free" />
    @else
        <x-webx-map :lat="$lat" :lng="$lng" :zoom="$scale" :height="$tall" :height-narrow="$narrow" :address="$place" :title="$name" :consent="$free" />
    @endif
</section>
@endif

styles:
.b-map {
    container-type: inline-size;
}

.b-map__heading {
    margin: 0 0 1em;
}

/* Edge to edge: the map to the window's sides, square; the heading keeps to the gutter. */
.b-map.site-bleed {
    --webx-map-radius: 0;
}

.b-map.site-bleed .b-map__heading {
    padding-inline: var(--site-gutter);
}
